#!/usr/bin/env node
//
// Generate src/externals/herdr/schema.ts from `herdr api schema --json`.
//
// The generated file is committed, so building yan needs no Herdr installed;
// this runs only when someone deliberately re-pins.
//
// What is generated is the version stamp and the enums yan actually acts on,
// never the request/response shapes, which are read field by field through
// narrowing. Herdr publishes around thirty enums and yan branches on two of
// them; generating the rest only gave the next reader thirty unions to work
// out which are load-bearing.
//
// Usage: node scripts/generate-herdr-types.mjs [--check]
//   --check  do not write; exit 1 if the committed file is out of date

import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const target = join(repoRoot, 'src', 'externals', 'herdr', 'schema.ts');
const check = process.argv.includes('--check');

let raw;
try {
  raw = execFileSync('herdr', ['api', 'schema', '--json'], {
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
} catch (err) {
  process.stderr.write(`generate-herdr-types: cannot run 'herdr api schema --json': ${err.message}\n`);
  process.exit(2);
}

const schema = JSON.parse(raw);

// The enums yan branches on. Anything not named here is Herdr's business:
// `AgentStatus` is what `yan state` reports about a shift, and `ReadSource`
// is the `--source` of `agent read`. A name that stops appearing in the
// schema is an error rather than a silent omission, because that is a Herdr
// change yan has to answer.
const WANTED = ['AgentStatus', 'ReadSource'];

/** The wanted `$defs` entries, which are plain string enums, across all five schemas. */
function collectEnums() {
  const found = new Map();
  for (const body of Object.values(schema.schemas ?? {})) {
    for (const [name, def] of Object.entries(body.$defs ?? {})) {
      if (!WANTED.includes(name)) continue;
      if (def && def.type === 'string' && Array.isArray(def.enum)) {
        const members = [...def.enum];
        const previous = found.get(name);
        if (previous !== undefined && previous.join('\0') !== members.join('\0')) {
          process.stderr.write(
            `generate-herdr-types: ${name} is defined twice with different members\n`,
          );
          process.exit(2);
        }
        found.set(name, members);
      }
    }
  }
  return [...found.entries()].sort(([a], [b]) => (a < b ? -1 : 1));
}

const enums = collectEnums();

const missing = WANTED.filter((name) => !enums.some(([found]) => found === name));
if (missing.length > 0) {
  process.stderr.write(
    `generate-herdr-types: this Herdr publishes no enum called ${missing.join(', ')} - yan reads it, so find out what replaced it\n`,
  );
  process.exit(2);
}

const lines = [
  '// GENERATED by scripts/generate-herdr-types.mjs. Do not edit by hand.',
  '//',
  '// Source: `herdr api schema --json`. Re-run the generator after a Herdr',
  '// upgrade; `yan doctor` compares the two stamps below against the installed',
  '// binary and says so when they have drifted.',
  '',
  `export const HERDR_PROTOCOL = ${JSON.stringify(schema.protocol)};`,
  `export const HERDR_SCHEMA_VERSION = ${JSON.stringify(schema.schema_version)};`,
  '',
];

for (const [name, members] of enums) {
  const union = members.map((m) => `'${m}'`).join(' | ');
  lines.push(`export type ${name} = ${union};`);
  lines.push(
    `export const ${name.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toUpperCase()}: readonly ${name}[] = [`,
  );
  for (const m of members) lines.push(`  '${m}',`);
  lines.push('];');
  lines.push('');
}

const generated = lines.join('\n');

if (check) {
  let current = '';
  try {
    current = readFileSync(target, 'utf8');
  } catch {
    current = '';
  }
  if (current !== generated) {
    process.stderr.write(
      'generate-herdr-types: src/externals/herdr/schema.ts is out of date - re-run the generator\n',
    );
    process.exit(1);
  }
  process.stdout.write('generate-herdr-types: up to date\n');
} else {
  writeFileSync(target, generated);
  process.stdout.write(
    `generate-herdr-types: wrote ${enums.length} enums for protocol ${schema.protocol}\n`,
  );
}
